  "PDF ↔ Word, PowerPoint → PDF, photos → PDF, scanned paper → editable Word, Excel ↔ CSV ↔ JSON, e-books, web pages, subtitles, merge and split PDFs — on your phone. Your files are never uploaded to a converter website.": "PDF ↔ Word, PowerPoint → PDF, photos → PDF, papier scanné → Word modifiable, Excel ↔ CSV ↔ JSON, livres numériques, pages web, sous-titres, fusion et découpe de PDF — sur votre téléphone. Vos fichiers ne sont jamais envoyés à un site de conversion.",
