  "Every part is checked: numbers, names and codes kept exactly.": "Chaque partie est vérifiée : nombres, noms et codes gardés exactement.",
  "Open a PDF, Word file, book or web page. Read it here and chat with it — every answer shows the page it came from. Everything stays on your phone.": "Ouvrez un PDF, un fichier Word, un livre ou une page web. Lisez-le ici et discutez avec lui — chaque réponse montre la page d'où elle vient. Tout reste sur votre téléphone.",
  "Open a file": "Ouvrir un fichier",
  "Reading and searching work now. To chat with the file, install a model in Engine.": "La lecture et la recherche fonctionnent déjà. Pour discuter avec le fichier, installez un modèle dans Moteur.",
  "Your documents appear here": "Vos documents apparaissent ici",
  "Open a file: it is kept on this device, with its chat and notes, so you can come back to it.": "Ouvrez un fichier : il est gardé sur cet appareil, avec sa discussion et ses notes, pour que vous puissiez y revenir.",
  "Stop": "Arrêter",
  "Describe it in one sentence — the AI on your phone writes a designed PowerPoint or a full report, from the web or your own file. Edit any slide, then save it as PowerPoint, Word or PDF.": "Décrivez-le en une phrase — l'IA de votre téléphone écrit un PowerPoint mis en page ou un rapport complet, à partir du web ou de votre propre fichier. Modifiez n'importe quelle diapositive, puis enregistrez en PowerPoint, Word ou PDF.",
  "Presentation": "Présentation",
  "Report": "Rapport",
  "e.g. A pitch for our café to offices in New Cairo: menu, catering, prices, why us": "ex. Une présentation de notre café aux bureaux du Nouveau Caire : carte, traiteur, prix, pourquoi nous",
  "Research the web for facts and figures": "Chercher des faits et chiffres sur le web",
  "Each slide names its sources, and a Sources slide lists every page": "Chaque diapositive cite ses sources, et une diapositive Sources liste chaque page",
  "Base it on my file (Word, PDF, Excel, CSV…)": "Me baser sur mon fichier (Word, PDF, Excel, CSV…)",
  "Make the presentation": "Créer la présentation",
  "{n} slides": "{n} diapositives",
  "Midnight": "Minuit",
  "Short points": "Points courts",
  "Change": "Changer",
  "Your slides appear here": "Vos diapositives apparaissent ici",
  "Each slide or section shows here as it is written.": "Chaque diapositive ou section s'affiche ici au fur et à mesure.",
  "Build a CV in English or Arabic, keep a copy for every job, and export a clean PDF or Word file. The AI on your phone helps with wording.": "Créez un CV en anglais ou en arabe, gardez une copie pour chaque poste, et exportez un PDF ou un Word propre. L'IA de votre téléphone aide à la formulation.",
  "New CV": "Nouveau CV",
  "Import my CV": "Importer mon CV",
  "No CVs yet": "Aucun CV pour l'instant",
  "Start a new one, or import the one you already have.": "Commencez-en un nouveau, ou importez celui que vous avez déjà.",
  "Copy a video's link, paste it here, pick the quality — it's saved to your phone's Movies folder. Works with direct video links, Google Drive, Dropbox, archive.org, Wikimedia Commons and pages that show a plain video.": "Copiez le lien d'une vidéo, collez-le ici, choisissez la qualité — elle est enregistrée dans le dossier Films de votre téléphone. Fonctionne avec les liens vidéo directs, Google Drive, Dropbox, archive.org, Wikimedia Commons et les pages qui affichent une vidéo simple.",
  "Find the video": "Trouver la vidéo",
  "The video's versions appear here": "Les versions de la vidéo apparaissent ici",
  "Paste a link and tap Find the video — then pick the quality to download.": "Collez un lien et touchez Trouver la vidéo — puis choisissez la qualité à télécharger.",
  "No map on this device yet": "Pas encore de carte sur cet appareil",
  "Download the world map to see every country, or your country's map for streets, places and offline search.": "Téléchargez la carte du monde pour voir chaque pays, ou la carte de votre pays pour les rues, les lieux et la recherche hors ligne.",
