  "Code that is tested before you get it": "Du code testé avant de vous être remis",
  "The model writes the program and its tests, the phone runs them, and any error goes straight back to the model to fix — until the tests pass. Offline, in a locked sandbox.": "Le modèle écrit le programme et ses tests, le téléphone les exécute, et toute erreur repart directement au modèle pour correction — jusqu'à ce que les tests passent. Hors ligne, dans un bac à sable verrouillé.",
  "What should it do? e.g. “A function that splits a restaurant bill between friends, with the tip”": "Que doit-il faire ? ex. « Une fonction qui partage l'addition du restaurant entre amis, avec le pourboire »",
