  "= instant filler removal (offline).": "= suppression instantanée du remplissage (hors ligne).",
  "= the model rewrites it far shorter while keeping the meaning.": "= le modèle le réécrit bien plus court en gardant le sens.",
  "Result": "Résultat",
  "Paste a wordy prompt and hit": "Collez un prompt verbeux et touchez",
  "— it thinks about meaning, not just filler words.": "— il réfléchit au sens, pas seulement aux mots de remplissage.",
  "Text to rewrite": "Texte à réécrire",
  "Paste AI-generated or stiff text — it comes back sounding like a person wrote it.": "Collez un texte généré par IA ou guindé — il revient comme écrit par une personne.",
  "Your writing sample": "Votre échantillon d'écriture",
  "(this is what makes it sound like you)": "(c'est ce qui le fait sonner comme vous)",
  "Paste a few paragraphs you wrote yourself — an email, a message, anything in your natural voice.": "Collez quelques paragraphes que vous avez écrits vous-même — un e-mail, un message, n'importe quoi dans votre voix naturelle.",
  "Keeps your meaning and facts exactly — changes only how it reads. The writing sample is optional but makes the biggest difference.": "Garde exactement votre sens et vos faits — ne change que la façon dont ça se lit. L'échantillon est facultatif mais fait la plus grande différence.",
  "Rewritten": "Réécrit",
  "Paste stiff or AI-sounding text, add a sample of your own writing, and it comes back in your voice — same meaning, human rhythm.": "Collez un texte guindé ou à l'air d'IA, ajoutez un échantillon de votre écriture, et il revient dans votre voix — même sens, rythme humain.",
  "Chat through Attune — it reads the whole conversation and sharpens every next prompt.": "Discutez via Attune — il lit toute la conversation et affine chaque prompt suivant.",
  "What do you want out of this whole conversation? (optional, but it makes every prompt better)": "Qu'attendez-vous de toute cette conversation ? (facultatif, mais chaque prompt en est meilleur)",
  "Bring the chat from {t} — paste the whole conversation or just its last reply:": "Apportez la discussion de {t} — collez toute la conversation ou seulement sa dernière réponse :",
  "Paste here…": "Collez ici…",
  "Read it & suggest my reply": "Le lire et suggérer ma réponse",
  "What do you want to ask? Type it however you like.": "Que voulez-vous demander ? Tapez-le comme vous voulez.",
  "Optimize my prompt": "Optimiser mon prompt",
  "The loop: type intent → get an optimized prompt → send it → bring the reply back → each next prompt is sharper. In the phone app, the share-sheet replaces copy-paste entirely.": "La boucle : tapez l'intention → obtenez un prompt optimisé → envoyez-le → rapportez la réponse → chaque prompt suivant est plus précis. Dans l'app, le menu Partager remplace entièrement le copier-coller.",
  "Ready prompt recipes — pick one, fill the blanks, then": "Des recettes de prompts prêtes — choisissez-en une, remplissez les blancs, puis",
