  "It answers from this device, and it can look through everything you've asked it before — so questions about your own work have real answers, not guesses.": "Il répond depuis cet appareil et peut parcourir tout ce que vous lui avez déjà demandé — les questions sur votre propre travail ont donc de vraies réponses, pas des suppositions.",
