  "Pro is bought in the Google Play version of Attune — one tap, paid by card or from your Vodafone / Orange / Etisalat balance, and it switches on by itself.": "Pro s'achète dans la version Google Play d'Attune — un seul toucher, payé par carte ou avec votre crédit Vodafone / Orange / Etisalat, et il s'active tout seul.",
  "Cancel any time in Google Play → Subscriptions. The plan renews by itself; nothing to send, nobody to message.": "Résiliez à tout moment dans Google Play → Abonnements. L'abonnement se renouvelle tout seul ; rien à envoyer, personne à contacter.",
