  "Keep": "Garder",
  "filing…": "classement…",
  "Free: keep and search everything. Pro: it files each item by itself (title, summary, tags), reads your photos and answers questions from your Mind.": "Gratuit : gardez et retrouvez tout. Pro : chaque élément est classé tout seul (titre, résumé, étiquettes), vos photos sont lues et vos questions trouvent réponse dans votre Esprit.",
  "Ask your Mind": "Interroger votre Esprit",
