  "Nothing in your Mind matched — so this is not from your items.": "Rien dans votre Esprit ne correspond — cette réponse ne vient donc pas de vos éléments.",
  "From your past": "De votre passé",
  "Nothing matches that.": "Rien ne correspond.",
