  "a year ago": "il y a un an",
  "from your past": "de votre passé",
  "Nothing to read in that.": "Rien à lire là-dedans.",
  "That payment did not go through, so there is nothing to record.": "Ce paiement n'a pas abouti, il n'y a donc rien à enregistrer.",
  "Sent to Yusr — pick the account and confirm": "Envoyé à Yusr — choisissez le compte et confirmez",
  "Money isn't bundled in this build.": "Argent n'est pas inclus dans cette version.",
  "The Yusr document wasn't embedded. On the phone it loads from local assets.": "Le document Yusr n'a pas été intégré. Sur le téléphone, il se charge depuis les fichiers de l'app.",
  "Your ledger and every zakāt ruling live here, unchanged, and free forever. Attune adds memory and plain language on top — it never calculates zakāt and never moves money on its own.": "Votre registre et toutes les règles de la zakat sont ici, inchangés et gratuits pour toujours. Attune ajoute la mémoire et des explications simples — il ne calcule jamais la zakat et ne déplace jamais d'argent de lui-même.",
  "Share a payment": "Partager un paiement",
  "An InstaPay confirmation, a bank SMS, a wallet receipt or a photo of one. Attune reads the amount and who it was, then opens your own transaction sheet with it filled in. You pick the account.": "Une confirmation InstaPay, un SMS de la banque, un reçu de portefeuille ou une photo de l'un d'eux. Attune lit le montant et le destinataire, puis ouvre votre fiche de transaction déjà remplie. C'est vous qui choisissez le compte.",
  "تم تحويل مبلغ 1,500.00 جنيه إلى AHMED MOHAMED. رقم العملية 987654321": "Virement de 1 500,00 EGP effectué vers AHMED MOHAMED. N° d'opération 987654321",
  "Read it": "Lire",
  "Reading…": "Lecture…",
  "From a photo": "Depuis une photo",
  "Three ways, all fine: share the SMS, WhatsApp message or screenshot to Attune from any app (it lands here by itself) · paste it above · or take/pick a photo of the receipt.": "Trois façons, toutes valables : partagez le SMS, le message WhatsApp ou la capture d'écran avec Attune depuis n'importe quelle app (il arrive ici tout seul) · collez-le ci-dessus · ou prenez/choisissez une photo du reçu.",
  "read from: “": "lu depuis : “",
  "· account: you choose, in Yusr": "· compte : c'est vous qui choisissez, dans Yusr",
  "Talk to your money": "Parlez à votre argent",
  "not saved to memory": "non enregistré en mémoire",
  "saved to memory": "enregistré en mémoire",
  "Answered on this device from the figures Yusr calculated. Ask follow-ups — it keeps the thread. For zakāt it is handed the app's own numbers and forbidden from recomputing them: it explains, it does not rule.": "Répondu sur cet appareil à partir des chiffres calculés par Yusr. Posez d'autres questions — le fil est conservé. Pour la zakat, il reçoit les chiffres de l'app et n'a pas le droit de les recalculer : il explique, il ne tranche pas.",
  "figures from Yusr's zakāt engine, not recalculated": "chiffres du moteur de zakat de Yusr, non recalculés",
  "ask a follow-up…": "posez une autre question…",
  "Thinking…": "Réflexion…",
  "What do you make of this?": "Qu'en pensez-vous ?",
  "Load a model in Engine and this answers with no signal.": "Chargez un modèle dans Moteur et ceci vous répondra même sans réseau.",
  "What stands out": "Ce qui ressort",
  "Every figure here is one Yusr calculated — the model may not produce a new number.": "Chaque chiffre ici a été calculé par Yusr — le modèle n'a pas le droit d'en produire un nouveau.",
  "What the AI is allowed to see": "Ce que l'IA a le droit de voir",
  "Sources:": "Sources :",
  "Added to memory": "Ajouté à la mémoire",
  "Only what you confirmed. Attune records nothing on its own.": "Seulement ce que vous avez confirmé. Attune n'enregistre rien de lui-même.",
  "No signal, so only your saved places are searchable — nothing matched.": "Pas de réseau : seuls vos lieux enregistrés sont consultables — aucun ne correspond.",
  "Nothing found for that.": "Aucun résultat.",
  "Saved — it works offline now": "Enregistrée — elle fonctionne maintenant hors ligne",
  "Map tiles cleared": "Tuiles de carte effacées",
  "Every area you look at is kept, so it works again with no signal. You can also download an area before you travel. Place search needs a connection; your own saved places are searchable without one.": "Chaque zone que vous consultez est gardée, elle fonctionne donc à nouveau sans réseau. Vous pouvez aussi télécharger une zone avant de voyager. La recherche de lieux demande une connexion ; vos lieux enregistrés se cherchent sans.",
  "offline — showing saved tiles": "hors ligne — tuiles enregistrées affichées",
