  "Translated by the AI on your phone — check important names and numbers.": "Traduit par l'IA de votre téléphone — vérifiez les noms et les chiffres importants.",
  "Translating needs an AI model — open Engine and install one.": "La traduction nécessite un modèle d'IA — ouvrez Moteur et installez-en un.",
  "The AI on your phone translates it piece by piece; headings, lists, tables and numbers stay in place. Long files take a few minutes.": "L'IA de votre téléphone traduit morceau par morceau ; titres, listes, tableaux et chiffres restent en place. Les longs fichiers prennent quelques minutes.",
