  "Audio only": "Audio seul",
  "Original": "Original",
  "Play": "Lire",
  "Waiting for the internet…": "En attente d'Internet…",
  "Only download videos you have the right to keep.": "Ne téléchargez que les vidéos que vous avez le droit de garder.",
  "The clipboard is empty — copy the video's link first": "Le presse-papiers est vide — copiez d'abord le lien de la vidéo",
  "Long-press the box and choose Paste": "Appuyez longuement sur le champ et choisissez Coller",
  "That isn't a link. Copy the video's link (it starts with https://) and paste it here.": "Ce n'est pas un lien. Copiez le lien de la vidéo (il commence par https://) et collez-le ici.",
  "{site} doesn't allow its videos to be downloaded, so Attune can't save them (Google Play removes apps that do). Links that work: direct video links, Google Drive, Dropbox, archive.org, Wikimedia Commons, and pages that show a plain video file.": "{site} n'autorise pas le téléchargement de ses vidéos, Attune ne peut donc pas les enregistrer (Google Play retire les apps qui le font). Liens qui fonctionnent : liens vidéo directs, Google Drive, Dropbox, archive.org, Wikimedia Commons et les pages qui affichent un simple fichier vidéo.",
  "a streaming service": "un service de streaming",
  "this site": "ce site",
  "That's a live-stream link (.m3u8) — it's streamed in pieces and can't be saved as one file.": "C'est un lien de diffusion en direct (.m3u8) — il est diffusé par morceaux et ne peut pas être enregistré en un seul fichier.",
  "Downloading works in the Android app.": "Le téléchargement fonctionne dans l'app Android.",
  "Google Drive didn't give the file — make sure it's shared as \"Anyone with the link\".": "Google Drive n'a pas fourni le fichier — vérifiez qu'il est partagé avec « Tous les utilisateurs qui ont le lien ».",
  "This page plays a {site} video, which can't be downloaded.": "Cette page lit une vidéo {site}, qui ne peut pas être téléchargée.",
  "This page streams its video in pieces (HLS), which can't be saved as one file.": "Cette page diffuse sa vidéo par morceaux (HLS), elle ne peut pas être enregistrée en un seul fichier.",
  "No downloadable video was found on that page.": "Aucune vidéo téléchargeable n'a été trouvée sur cette page.",
  "That link didn't give a video file (the site sent {t}).": "Ce lien n'a pas renvoyé de fichier vidéo (le site a envoyé {t}).",
  "No downloadable video was found there.": "Aucune vidéo téléchargeable n'a été trouvée.",
  "Free includes 3 video downloads a day — Pro is unlimited": "La version gratuite inclut 3 téléchargements de vidéos par jour — Pro est illimité",
  "Downloading — you can close Attune, it keeps going": "Téléchargement en cours — vous pouvez fermer Attune, il continue",
  "The file was moved or deleted": "Le fichier a été déplacé ou supprimé",
  "The download failed — the link may have expired. Find it again and retry.": "Le téléchargement a échoué — le lien a peut-être expiré. Retrouvez-le et réessayez.",
  "PDF · Word · PowerPoint · Excel · CSV · photos · e-books · web pages · subtitles — several photos → one PDF, several PDFs → merged": "PDF · Word · PowerPoint · Excel · CSV · photos · livres numériques · pages web · sous-titres — plusieurs photos → un PDF, plusieurs PDF → fusionnés",
