  ". Entry rules change with no notice and the cost of being wrong is a denied boarding — confirm with the embassy or the official portal before you book.": ". Les règles d'entrée changent sans préavis et une erreur peut coûter un refus d'embarquement — confirmez auprès de l'ambassade ou du portail officiel avant de réserver.",
  "When you land": "À votre arrivée",
  "first hour": "première heure",
