  "install before you fly": "à installer avant de partir",
  "Some of these can't be installed or signed up for once you're in the country — do it while you still have your home connection.": "Certaines ne peuvent plus être installées ni créées une fois dans le pays — faites-le tant que vous avez encore votre connexion habituelle.",
