  "It knows how things actually work here — fair prices, common overcharges, what's rude. It will tell you when something needs live data it can't have offline.": "Il sait comment les choses se passent vraiment ici : prix justes, arnaques courantes, ce qui est impoli. Il vous dira quand il faut des données en direct qu'il ne peut pas avoir hors ligne.",
