  "Tap to copy. These are written by hand, not generated — so an allergy or emergency phrase can never come out wrong.": "Touchez pour copier. Elles sont écrites à la main, pas générées : une phrase sur une allergie ou une urgence ne peut donc jamais être fausse.",
