  "This model is large for this phone. It works, but answers come slowly and the phone gets warm. For quick, smooth answers use Qwen 3.5 4B — same Arabic, reads photos, about 3× faster.": "Ce modèle est volumineux pour ce téléphone. Il fonctionne, mais les réponses sont lentes et le téléphone chauffe. Pour des réponses rapides et fluides, utilisez Qwen 3.5 4B : même arabe, lit les photos, environ 3 fois plus rapide.",
