  "Delete": "Supprimer",
  "Installed weights never update on their own, so a prompt that works today works the same way in a year. The fingerprint proves exactly which file is answering.": "Les poids installés ne se mettent jamais à jour d'eux-mêmes : un prompt qui marche aujourd'hui marchera pareil dans un an. L'empreinte prouve exactement quel fichier répond.",
  "Add any model": "Ajouter un modèle",
  "unsloth/Qwen3.5-9B-GGUF:Q4_K_M   or   https://…/model.gguf": "unsloth/Qwen3.5-9B-GGUF:Q4_K_M   ou   https://…/model.gguf",
  "Any GGUF on Hugging Face as": "N'importe quel GGUF sur Hugging Face sous la forme",
  ", or a direct https link. Specialist and fine-tuned models install the same way — the photo reader is fetched too when the repo has one.": ", ou un lien https direct. Les modèles spécialisés et affinés s'installent de la même façon — le lecteur de photos est aussi téléchargé quand le dépôt en propose un.",
  "How it answers": "Sa façon de répondre",
  "e.g. I run a small shop in Egypt. Answer in Egyptian Arabic unless I write in English. Give prices in EGP.": "p. ex. Je tiens une petite boutique en Égypte. Réponds en arabe égyptien, sauf si j'écris en français. Donne les prix en EGP.",
  "Saved when you tap outside the box. Stays on this phone.": "Enregistré quand vous touchez en dehors du cadre. Reste sur ce téléphone.",
  "Web lookup": "Recherche web",
  "Only the question you look up and the pages opened leave the phone — never your conversation, files or memory.": "Seules la question recherchée et les pages ouvertes quittent le téléphone — jamais votre conversation, vos fichiers ni votre mémoire.",
