  "Storage:": "Stockage :",
  "Compute": "Calcul",
  "Prefill runs where compute is fastest, decode where bandwidth is. Using both raises usable bandwidth ~43 → 59 GB/s.": "Le préremplissage s'exécute là où le calcul est le plus rapide, le décodage là où la bande passante l'est. Utiliser les deux fait passer la bande passante exploitable d'environ 43 à 59 Go/s.",
