  "Merge": "Fusionner",
  "Keep everything on this phone and add the backup's chats, memory, reminders and cycle days. The Money ledger is only taken from the backup if this phone has none.": "Garder tout ce qui est sur ce téléphone et ajouter les discussions, la mémoire, les rappels et les jours de cycle de la sauvegarde. Le livre de comptes Argent n'est repris de la sauvegarde que si ce téléphone n'en a pas.",
  "This phone's {c} chats and {l} ledger entries will be replaced by the backup's. You can undo this once, right after.": "Les {c} discussions et {l} écritures de ce téléphone seront remplacées par celles de la sauvegarde. Vous pourrez annuler une fois, juste après.",
  "The backup's items will be added to this phone. You can undo this once, right after.": "Les éléments de la sauvegarde seront ajoutés à ce téléphone. Vous pourrez annuler une fois, juste après.",
