  "Name the outcome; it fills in the path.": "Nommez le résultat ; il remplit le chemin.",
  "Huge window — compress for cost, not for fit.": "Fenêtre immense — compressez pour le coût, pas pour la faire tenir.",
  "Direct phrasing; ask for reasoning explicitly.": "Formulation directe ; demandez explicitement le raisonnement.",
  "Structured reasoning; keep numbered steps.": "Raisonnement structuré ; gardez les étapes numérotées.",
  "Strong multilingual — keep the source language.": "Très bon multilingue — gardez la langue source.",
  "Concise by nature; over-compressing loses nuance.": "Concis par nature ; trop compresser fait perdre des nuances.",
  "Open weights; explicit instructions beat implied ones.": "Poids ouverts ; les consignes explicites valent mieux que les sous-entendus.",
  "Long documents are its strength; keep headings.": "Les longs documents sont sa force ; gardez les titres.",
  "Code context competes for the window — trim prose first.": "Le code concurrence la fenêtre — coupez d'abord la prose.",
  "A search tool — keep the sources, cut the styling.": "Un outil de recherche — gardez les sources, coupez la mise en forme.",
  "Tight. Cut everything that isn't the instruction.": "Serré. Coupez tout ce qui n'est pas la consigne.",
