  "Suggested. The free tier stops when it runs out instead of charging you.": "Suggéré. L'offre gratuite s'arrête quand elle est épuisée au lieu de vous facturer.",
  "Needs a card on file. An independent index — good in English, unproven in Arabic.": "Nécessite une carte enregistrée. Un index indépendant — bon en anglais, non éprouvé en arabe.",
  "Returns Google's own results, so the best Arabic quality of the three.": "Renvoie les propres résultats de Google, donc la meilleure qualité en arabe des trois.",
  "as a table": "sous forme de tableau",
  "step by step": "étape par étape",
  "with examples": "avec des exemples",
  "for a beginner": "pour un débutant",
  "corrected by you": "corrigé par vous",
  "Free": "Gratuit",
  "$99.99/yr · $299.99 once, forever": "99,99 $/an · 299,99 $ une fois, pour toujours",
  "On-device": "Sur l'appareil",
  "The only mode. Nothing leaves this device.": "Le seul mode. Rien ne quitte cet appareil.",
  "Write a polite reply to this message: ": "Rédige une réponse polie à ce message : ",
  "Translate into English: ": "Traduis en français : ",
  "Summarise this in 3 bullets: ": "Résume ceci en 3 points : ",
  "What should I check on a used car before I buy it?": "Que dois-je vérifier sur une voiture d'occasion avant de l'acheter ?",
  "My period started this morning, medium flow": "Mes règles ont commencé ce matin, flux moyen",
  "Add it to your ledger in Money? You'll pick the account and confirm there.": "L'ajouter à votre livre de comptes dans Argent ? Vous y choisirez le compte et confirmerez.",
  "Spotting": "Spotting",
  "Light": "Léger",
  "Medium": "Moyen",
  "Heavy": "Abondant",
  "item": "élément",
  "items": "éléments",
  "15 questions a day": "15 questions par jour",
  "3 templates · 5 history items": "3 modèles · 5 éléments d'historique",
  "35B of knowledge, 3B doing the work on each token — near-frontier answers at a speed a laptop can sustain. A mixture-of-experts model keeps every expert in memory even though few run per token, so this needs the RAM of a 35B and the compute of a 3B.": "35B de connaissances, 3B qui travaillent à chaque jeton — des réponses proches de l'état de l'art à une vitesse qu'un ordinateur portable peut tenir. Un modèle à mélange d'experts garde tous les experts en mémoire même si peu s'exécutent par jeton : il faut donc la RAM d'un 35B et la puissance de calcul d'un 3B.",
  "A bigger length budget for reports, plans and analysis.": "Un budget de longueur plus grand pour les rapports, plans et analyses.",
  "Ask it as much as you like — no daily limit": "Posez-lui autant de questions que vous voulez — aucune limite quotidienne",
  "Your phone reports {n} GB of memory": "Votre téléphone indique {n} Go de mémoire",
  "Your computer reports {n} GB of memory": "Votre ordinateur indique {n} Go de mémoire",
  "which is comfortable for everyday use": "ce qui est confortable pour un usage quotidien",
  "which is enough, with shorter conversations": "ce qui suffit, avec des conversations plus courtes",
  ", ": ", ",
  "Documents, fleet records, copilot, every domain pack": "Documents, données de flotte, copilote, tous les packs de domaine",
  "Small enough to download on mobile data if you need to.": "Assez léger pour être téléchargé en données mobiles si nécessaire.",
  "This is a large model for a phone. It will run, and it will slow down noticeably once the phone gets warm — keep answers short, or pick the smaller one.": "C'est un gros modèle pour un téléphone. Il fonctionnera, mais ralentira nettement quand le téléphone chauffera — gardez les réponses courtes, ou choisissez le plus petit.",
  "Every tool, and all 31 country packs": "Tous les outils et les 31 packs pays",
  "Finds what you promised people, from your own words": "Retrouve ce que vous avez promis aux gens, d'après vos propres mots",
  "Fixed randomness, so a workflow gives identical output every time it runs.": "Hasard fixé : un flux de travail donne un résultat identique à chaque exécution.",
  "Free web search: DuckDuckGo, Bing and Mojeek at once, then the top pages are read in full, so answers come from real passages.": "Recherche web gratuite : DuckDuckGo, Bing et Mojeek à la fois, puis les meilleures pages sont lues en entier, pour que les réponses viennent de vrais passages.",
  "Free · no key": "Gratuit · sans clé",
  "Installing… {p}%": "Installation… {p} %",
  "It remembers everything and can search it": "Il se souvient de tout et peut tout retrouver",
  "Learns your vocabulary and writes the way you do": "Apprend votre vocabulaire et écrit comme vous",
  "No account, no sign-in, nothing uploaded": "Sans compte, sans connexion, rien d'envoyé",
  "Running": "En cours",
  "Loading the model…": "Chargement du modèle…",
  "Nothing in the app can reach the internet — no web lookup, no maps, no downloads. The model and everything on the phone keep working.": "Rien dans l'application ne peut accéder à internet — ni recherche web, ni cartes, ni téléchargements. Le modèle et tout ce qui est sur le téléphone continuent de fonctionner.",
  "The model reasons first on every question. Clearly better on hard problems, but on a phone the answer starts 30–90 s later. Off: tap “Think” on just the questions that need it.": "Le modèle réfléchit d'abord à chaque question. Nettement meilleur sur les problèmes difficiles, mais sur un téléphone la réponse démarre 30 à 90 s plus tard. Désactivé : touchez « Réfléchir » seulement pour les questions qui en ont besoin.",
  "The same model as below, given the memory to hold a whole book of context at once. On a 48 GB machine the spare RAM is better spent on context than on precision — you can hand it an entire contract or a year of notes and it keeps all of it in view.": "Le même modèle que ci-dessous, avec la mémoire nécessaire pour tenir tout un livre de contexte d'un coup. Sur une machine de 48 Go, la RAM en réserve vaut mieux dépensée en contexte qu'en précision — vous pouvez lui donner un contrat entier ou un an de notes et il garde tout en vue.",
  "The whole assistant, on your device": "L'assistant complet, sur votre appareil",
  "Works entirely offline. No account, ever.": "Fonctionne entièrement hors ligne. Jamais de compte.",
