  "Notifications are off for Attune — tap to allow them, or reminders can't appear.": "Les notifications sont désactivées pour Attune — touchez pour les autoriser, sinon les rappels ne peuvent pas apparaître.",
  "Reminders may come up to 10 minutes late. Tap to allow “Alarms & reminders” for Attune so they ring on the minute.": "Les rappels peuvent arriver avec jusqu'à 10 minutes de retard. Touchez pour autoriser « Alarmes et rappels » pour Attune afin qu'ils sonnent à la minute près.",
  "In the browser reminders are only listed — the Android app rings them.": "Dans le navigateur, les rappels sont seulement listés — l'application Android les fait sonner.",
  "from a promise": "d'après une promesse",
