  "What are the key points?": "Quels sont les points clés ?",
  "Checklist: what every answer must satisfy (one per line, optional)": "Liste de contrôle : ce que chaque réponse doit respecter (un point par ligne, facultatif)",
  "Facts the AI should know (prices, rules, terms — optional)": "Faits que l'IA doit connaître (prix, règles, conditions — facultatif)",
  "Separate topics with an empty line. Only the paragraphs that fit the question are used, so this can be long.": "Séparez les sujets par une ligne vide. Seuls les paragraphes qui correspondent à la question sont utilisés, le texte peut donc être long.",
  "Facts": "Faits",
  "It also runs this small program on your phone (offline, in a locked box — no internet, no files, no access to the app)": "Il exécute aussi ce petit programme sur votre téléphone (hors ligne, dans une boîte verrouillée — sans internet, sans fichiers, sans accès à l'application)",
  "Edit or improve my CV": "Modifier ou améliorer mon CV",
  "Say what to add or change («add my job at Dar Al Fouad Hospital as a nurse, 2019–2022», «change my phone to …»), or leave it empty and just make it more professional. You see the result before it is kept.": "Dites quoi ajouter ou changer (« ajoute mon poste d'infirmier à l'hôpital Dar Al Fouad, 2019–2022 », « change mon téléphone en … »), ou laissez vide pour simplement le rendre plus professionnel. Vous voyez le résultat avant qu'il soit conservé.",
  "What should be added or changed? (optional)": "Que faut-il ajouter ou changer ? (facultatif)",
  "Apply my change": "Appliquer ma modification",
  "Change + make it professional": "Modifier + rendre professionnel",
  "New version": "Nouvelle version",
  "Use this version": "Utiliser cette version",
  "Done — you can undo it": "Fait — vous pouvez annuler",
  "Undo the last change": "Annuler la dernière modification",
  "Stuck — starting again from scratch with a different approach": "Bloqué — on repart de zéro avec une autre approche",
  "Wrote it, with {n} tests.": "Écrit, avec {n} tests.",
  "Your programs": "Vos programmes",
  "not passing": "ne passe pas",
  "passing": "passe",
  "✓ Passed all {n} tests.": "✓ A réussi les {n} tests.",
  "✓ Ran without errors.": "✓ Exécuté sans erreur.",
  "The fix did not match the code.": "Le correctif ne correspondait pas au code.",
  "The model answered without code.": "Le modèle a répondu sans code.",
  "The fix deleted the tests — refused.": "Le correctif supprimait les tests — refusé.",
  "The model answered without any code — try asking again in other words.": "Le modèle a répondu sans aucun code — réessayez en reformulant.",
  "A picture — Studio draws it on this phone": "Une image — Studio la dessine sur ce téléphone",
  "Another version": "Autre version",
  "Could not open that picture": "Impossible d'ouvrir cette image",
  "Could not save": "Impossible d'enregistrer",
  "Current photo quality in 4 steps: people, places, products and text in pictures. Also edits a photo you give it (“make it night”, “remove the car”).": "Qualité photo actuelle en 4 étapes : personnes, lieux, produits et texte dans les images. Modifie aussi une photo que vous lui donnez (« fais-en une nuit », « enlève la voiture »).",
  "Describe the picture, in Arabic or English — e.g. “a felucca on the Nile at sunset”": "Décrivez l'image, en arabe ou en français — p. ex. « une felouque sur le Nil au coucher du soleil »",
  "Developing the picture…": "Développement de l'image…",
  "Download it on Wi-Fi. After that, pictures are made with no internet at all.": "Téléchargez-le en Wi-Fi. Ensuite, les images se créent sans aucun internet.",
  "Draw it": "La dessiner",
  "Draw it in Studio": "La dessiner dans Studio",
  "A place — Maps finds it": "Un lieu — Cartes le trouve",
  "Show on the map": "Afficher sur la carte",
  "Draw on the graphics chip (faster; switches itself off if the driver fails)": "Dessiner sur la puce graphique (plus rapide ; se désactive si le pilote échoue)",
  "Drawing on the GPU failed, so Attune switched Studio to the CPU. ": "Le dessin sur le GPU a échoué, Attune a donc basculé Studio sur le processeur. ",
  "Drawing — step {n} of {t}": "Dessin — étape {n} sur {t}",
  "Each picture is made by a separate engine process: when it finishes, all its memory goes back to the phone. Nothing is uploaded.": "Chaque image est créée par un processus de moteur distinct : à la fin, toute sa mémoire est rendue au téléphone. Rien n'est envoyé en ligne.",
  "Edit a photo": "Modifier une photo",
  "Edit it": "La modifier",
  "Edit this": "Modifier ceci",
  "GB, once": "Go, une fois",
  "Install the picture model first (Studio).": "Installez d'abord le modèle d'image (Studio).",
  "Install the sharpening model first (Studio).": "Installez d'abord le modèle de netteté (Studio).",
  "Install · {s} GB": "Installer · {s} Go",
  "Landscape": "Paysage",
  "Loading the picture model…": "Chargement du modèle d'image…",
  "Loading the picture model… {p}%": "Chargement du modèle d'image… {p} %",
  "Makes a finished picture four times bigger and sharper — for printing or zooming in.": "Rend une image terminée quatre fois plus grande et plus nette — pour l'impression ou le zoom.",
  "Pick a photo": "Choisir une photo",
