  "Reading your description…": "Lecture de votre description…",
  "Save to gallery": "Enregistrer dans la galerie",
  "Saved to {w}": "Enregistré dans {w}",
  "Saving to the gallery needs Android 10 or newer — use Share instead.": "L'enregistrement dans la galerie nécessite Android 10 ou plus — utilisez Partager à la place.",
  "Saving…": "Enregistrement…",
  "Sharpening ×4": "Netteté ×4",
  "Sharpening ×4 — part {n} of {t}": "Netteté ×4 — partie {n} sur {t}",
  "Square": "Carré",
  "Starting the download…": "Démarrage du téléchargement…",
  "Starting the picture engine…": "Démarrage du moteur d'image…",
  "Studio works in the Android app.": "Studio fonctionne dans l'application Android.",
  "The chat model was paused to make room, and is loading again.": "Le modèle de discussion a été mis en pause pour faire de la place, et se recharge.",
  "This APK has no picture engine yet — it comes with the next APK built on GitHub.": "Cet APK n'a pas encore de moteur d'image — il arrivera avec le prochain APK construit sur GitHub.",
  "This build draws on the CPU.": "Cette version dessine sur le processeur.",
  "This build of the app has no picture engine yet.": "Cette version de l'application n'a pas encore de moteur d'image.",
  "This phone has {n} GB — it may be too little for pictures.": "Ce téléphone a {n} Go — c'est peut-être trop peu pour les images.",
  "This version of Attune has no graphics-chip picture engine, so pictures are drawn on the CPU (slower). An update adds it.": "Cette version d'Attune n'a pas de moteur d'image pour puce graphique, les images sont donc dessinées sur le processeur (plus lent). Une mise à jour l'ajoutera.",
  "The picture engine stopped responding while loading the model, so it was stopped. Engine → Engine log shows its last lines — send them to support.": "Le moteur d'image a cessé de répondre pendant le chargement du modèle et a été arrêté. Moteur → Journal du moteur affiche ses dernières lignes — envoyez-les au support.",
  "This phone's GPU driver did not answer, so pictures are drawn on the CPU (slower).": "Le pilote GPU de ce téléphone n'a pas répondu, les images sont donc dessinées sur le processeur (plus lent).",
  "What should change? e.g. “make it night, with the street lights on”": "Que faut-il changer ? p. ex. « fais-en une nuit, avec les lampadaires allumés »",
  "Write a fuller description first (better pictures; uses the chat model)": "Écrire d'abord une description plus complète (meilleures images ; utilise le modèle de discussion)",
  "Writing a fuller description…": "Rédaction d'une description plus complète…",
  "needs {n} GB RAM": "nécessite {n} Go de RAM",
  "{m} is ready": "{m} est prêt",
  "×4 sharper": "×4 plus net",
  "drawn on the {b} in {t}": "dessiné sur {b} en {t}",
  "sharpened on the {b} in {t}": "affiné sur {b} en {t}",
  "Newest": "Plus récents",
  "stopped a repeat": "répétition évitée",
  "Checked by running code on this phone": "Vérifié en exécutant du code sur ce téléphone",
  "It printed:": "Il a affiché :",
  "fixed {n}×": "corrigé {n}×",
  "I couldn't make every test pass yet — here is the closest version; tap “Test & fix in Code” to keep going.": "Je n'ai pas encore réussi à faire passer tous les tests — voici la version la plus proche ; touchez « Tester et corriger dans Code » pour continuer.",
  "Working it out as a program…": "Calcul sous forme de programme…",
  "Fixing the program and running it again…": "Correction du programme et nouvelle exécution…",
  "Checked by running code — writing the answer…": "Vérifié en exécutant du code — rédaction de la réponse…",
  "Looking at the photo…": "Observation de la photo…",
  "Searching the web…": "Recherche sur le web…",
  "FLUX.2 klein 4B · high quality": "FLUX.2 klein 4B · haute qualité",
  "The best pictures this phone can make: the 8-bit build of FLUX.2 klein — finer detail, cleaner faces, hands and text. Also edits your photos by instruction.": "Les meilleures images que ce téléphone peut produire : la version 8 bits de FLUX.2 klein — détails plus fins, visages, mains et texte plus nets. Modifie aussi vos photos sur instruction.",
  "That file is too large (15 MB at most)": "Ce fichier est trop volumineux (15 Mo maximum)",
  "What's in this file? Summarise what matters.": "Que contient ce fichier ? Résume ce qui compte.",
  "Checked — the reviewer fixed a mistake": "Vérifié — le relecteur a corrigé une erreur",
