  "Wrong? Teach the right answer": "Faux ? Apprenez-lui la bonne réponse",
  "What should it have said? Chat will answer this way next time you ask something like it.": "Qu'aurait-il dû dire ? Discussion répondra ainsi la prochaine fois que vous poserez une question semblable.",
  "The right answer": "La bonne réponse",
