  "None yet — add a field of type “Link to another table”, or ask below: “connect Jobs to Customers”.": "Aucun pour l'instant — ajoutez un champ de type « Lien vers un autre tableau », ou demandez ci-dessous : « relie Chantiers à Clients ».",
