  "Make the form": "Créer le formulaire",
  "Load a model to make forms in words.": "Chargez un modèle pour créer des formulaires avec des mots.",
  "Form saved — pick it above the records when you add one": "Formulaire enregistré — choisissez-le au-dessus des enregistrements quand vous en ajoutez un",
  "Save form": "Enregistrer le formulaire",
  "No forms yet. A form shows only the fields you need, in your order, with ready values — pick it when you add a record.": "Aucun formulaire pour l'instant. Un formulaire n'affiche que les champs utiles, dans votre ordre, avec des valeurs prêtes — choisissez-le quand vous ajoutez un enregistrement.",
  "Pasted from {t}": "Collé depuis {t}",
  "Copy & open {t}": "Copier et ouvrir {t}",
  "Queries": "Requêtes",
  "Forms": "Formulaires",
  "Open an app file (made with Attune)": "Ouvrir un fichier d'application (créé avec Attune)",
  "That file isn't an app made with Attune Business.": "Ce fichier n'est pas une application créée avec Attune Entreprise.",
  "Updated from the app file — {n} tables with their records": "Mis à jour depuis le fichier d'application — {n} tableaux avec leurs enregistrements",
  "Opened — {n} tables with their records": "Ouvert — {n} tableaux avec leurs enregistrements",
  "Change the design in words — add fields to any table, new tables, links…": "Changez la conception avec des mots — ajoutez des champs à un tableau, de nouveaux tableaux, des liens…",
  "e.g. add Email and Tax ID to Suppliers, and a Warranty months field to Parts": "p. ex. ajoute E-mail et N° fiscal à Fournisseurs, et un champ Mois de garantie à Pièces",
  "Saved — send this file; it opens in any browser, no Attune needed": "Enregistré — envoyez ce fichier ; il s'ouvre dans n'importe quel navigateur, sans Attune",
  "Excel files need Python, which isn't in this build — use CSV.": "Les fichiers Excel nécessitent Python, absent de cette version — utilisez le CSV.",
  "Making the Excel file…": "Création du fichier Excel…",
  "Couldn't make the Excel file: {e}": "Impossible de créer le fichier Excel : {e}",
  "Give it to your team as an app: one file with all the data inside — it opens in any phone or computer browser, no Attune needed. When something needs changing, open the file here (Business → Open an app file), ask the AI, and send the new app back.": "Donnez-le à votre équipe sous forme d'application : un seul fichier avec toutes les données — il s'ouvre dans le navigateur de n'importe quel téléphone ou ordinateur, sans Attune. Quand il faut modifier quelque chose, ouvrez le fichier ici (Entreprise → Ouvrir un fichier d'application), demandez à l'IA, puis renvoyez la nouvelle application.",
  "Export as an app": "Exporter sous forme d'application",
  "Excel workbook (all tables)": "Classeur Excel (tous les tableaux)",
  "The picture engine stopped before the picture was finished — Android may have closed it to free memory. Try “Quick draft”, or close other apps and try again.": "Le moteur d'image s'est arrêté avant la fin de l'image — Android l'a peut-être fermé pour libérer de la mémoire. Essayez « Brouillon rapide », ou fermez d'autres applications et réessayez.",
  "The picture could not be made. Open Engine → Engine log and send me what it says.": "L'image n'a pas pu être créée. Ouvrez Moteur → Journal du moteur et envoyez-moi ce qu'il indique.",
  "Multi-token prediction (faster writing)": "Prédiction multi-jetons (écriture plus rapide)",
  "Off by default: on some phones it doubles words and digits (“ItIt is is”, “20205”). Turn it on only if answers stay correct.": "Désactivée par défaut : sur certains téléphones, elle double les mots et les chiffres (« IlIl est est », « 20205 »). Activez-la seulement si les réponses restent correctes.",
  "The last picture didn't finish:": "La dernière image n'a pas abouti :",
  "Connected {n} fields to their tables": "{n} champs reliés à leurs tableaux",
  "Connect the tables for me ({n})": "Relier les tableaux pour moi ({n})",
  "Connected {n} fields — Undo (top) puts them back": "{n} champs reliés — Annuler (en haut) les remet comme avant",
  "Connect the tables": "Relier les tableaux",
  "Something went wrong on this screen.": "Une erreur s'est produite sur cet écran.",
  "Your chats and data are safe. Try again — if it keeps happening, send me this message.": "Vos discussions et vos données sont en sécurité. Réessayez — si cela continue, envoyez-moi ce message.",
