  "Studio Turbo": "Studio Turbo",
  "Studio Pro": "Studio Pro",
  "Studio Pro HD": "Studio Pro HD",
  "Turbo · about 1 min": "Turbo · environ 1 min",
  "Studio Turbo+": "Studio Turbo+",
  "Recommended for your phone": "Recommandé pour votre téléphone",
  "Studio Ultra": "Studio Ultra",
  "Ultra · best quality, slow · {s} GB": "Ultra · meilleure qualité, lent · {s} Go",
  "best quality, slow": "meilleure qualité, lent",
  "fastest pictures": "images les plus rapides",
  "a graphics card with 8 GB or more: the most capable model": "une carte graphique de 8 Go ou plus : le modèle le plus performant",
  "The most capable model: text inside pictures, busy scenes, people. Slow on a phone (about 10 minutes a picture), fast on a computer with a graphics card. Needs 12 GB RAM.": "Le modèle le plus performant : texte dans les images, scènes chargées, personnes. Lent sur un téléphone (environ 10 minutes par image), rapide sur un ordinateur avec carte graphique. Nécessite 12 Go de RAM.",
  "about {s} s a picture": "environ {s} s par image",
  "8 GB or more and fast cores: the sharper XL model in one step": "8 Go ou plus et des cœurs rapides : le modèle XL plus net en une seule étape",
  "not enough free storage or speed for the XL model": "pas assez de stockage libre ou de vitesse pour le modèle XL",
  "the fast model fits this phone's memory": "le modèle rapide tient dans la mémoire de ce téléphone",
  "little memory or slow cores: smaller pictures, still clear": "peu de mémoire ou cœurs lents : images plus petites, toujours nettes",
  "Turbo+ · about 20 s · {s} GB": "Turbo+ · environ 20 s · {s} Go",
  "Faster and sharper than Turbo, with a better match to what you ask for: about 20 seconds a picture on the CPU. 512 px. For phones with 8 GB RAM or more.": "Plus rapide et plus net que Turbo, avec une meilleure fidélité à votre demande : environ 20 secondes par image sur le processeur. 512 px. Pour les téléphones de 8 Go de RAM ou plus.",
  "Pro · best quality": "Pro · meilleure qualité",
  "Pro on this phone's CPU: 10–20 min a picture": "Pro sur le processeur de ce téléphone : 10 à 20 min par image",
  "This phone's graphics chip isn't working with Studio, so the Pro model would take 10–20 minutes a picture on the CPU. Studio Turbo makes a picture in about a minute.": "La puce graphique de ce téléphone ne fonctionne pas avec Studio, le modèle Pro prendrait donc 10 à 20 minutes par image sur le processeur. Studio Turbo fait une image en environ une minute.",
  "Fast pictures on any phone: about a minute without a graphics chip, seconds with one. 512 px — great for ideas, drafts and posts.": "Des images rapides sur n'importe quel téléphone : environ une minute sans puce graphique, quelques secondes avec. 512 px — idéal pour les idées, les brouillons et les publications.",
  "The best photo quality: people, places, products and text in pictures, 1024 px. Also edits a photo you give it (“make it night”, “remove the car”). Needs a working graphics chip — on the CPU a picture takes 10–20 minutes.": "La meilleure qualité photo : personnes, lieux, produits et texte dans les images, 1024 px. Modifie aussi une photo que vous lui donnez (« fais-en une nuit », « enlève la voiture »). Nécessite une puce graphique fonctionnelle — sur le processeur, une image prend 10 à 20 minutes.",
  "Studio Pro at full precision: finer detail, cleaner faces, hands and text. Also edits your photos by instruction. Needs a working graphics chip and 12 GB RAM.": "Studio Pro en pleine précision : détails plus fins, visages, mains et texte plus nets. Modifie aussi vos photos sur instruction. Nécessite une puce graphique fonctionnelle et 12 Go de RAM.",
  "Still working — nothing is stuck. Turbo takes about 1–2 minutes on the CPU. Keep Attune open; Stop cancels it.": "Toujours en cours — rien n'est bloqué. Turbo prend environ 1 à 2 minutes sur le processeur. Gardez Attune ouverte ; Arrêter l'annule.",
  "Still working — nothing is stuck. Without the graphics chip a Pro picture takes 10–20 minutes (edits take longer). For speed, pick Turbo. Keep Attune open; Stop cancels it.": "Toujours en cours — rien n'est bloqué. Sans puce graphique, une image Pro prend 10 à 20 minutes (les modifications, plus). Pour la rapidité, choisissez Turbo. Gardez Attune ouverte ; Arrêter l'annule.",
  "Delete this chat?": "Supprimer cette discussion ?",
  "This can't be undone.": "Cette action est irréversible.",
  "Delete this reminder?": "Supprimer ce rappel ?",
  "Delete this project?": "Supprimer ce projet ?",
  "Remove this crane from the fleet?": "Retirer cette grue de la flotte ?",
  "Remove this from the project?": "Retirer ceci du projet ?",
