  "Delete this action?": "Supprimer cette action ?",
  "Spark (helper)": "Spark (assistant)",
  "Only works with Spark, Glow, Core and Zenith — not with the model in use.": "Ne fonctionne qu'avec Spark, Glow, Core et Zenith — pas avec le modèle utilisé.",
  "Download Spark as a helper (about 0.5 GB, once). Works with Glow, Core and Zenith.": "Téléchargez Spark comme assistant (environ 0,5 Go, une fois). Fonctionne avec Glow, Core et Zenith.",
  "This is a big model for a phone — Core is about 2–3× faster.": "C'est un gros modèle pour un téléphone — Core est environ 2 à 3 fois plus rapide.",
  "The strongest model a 12 GB phone can run: expert answers, and the best at reading documents and photos.": "Le modèle le plus puissant qu'un téléphone de 12 Go puisse faire tourner : des réponses d'expert, et le meilleur pour lire des documents et des photos.",
  "Core made 10% smaller for a 4 GB phone — worth it over Glow.": "Core réduit de 10 % pour un téléphone de 4 Go — préférable à Glow.",
  "Runs on a budget phone and still reads photos. Good short answers; long reasoning shows its size.": "Tourne sur un téléphone d'entrée de gamme et lit quand même les photos. De bonnes réponses courtes ; le raisonnement long montre sa taille.",
  "For a phone that can't hold anything else: tidying and shortening text. Not for reasoning.": "Pour un téléphone qui ne peut rien contenir d'autre : nettoyer et raccourcir du texte. Pas pour raisonner.",
  "The biggest speed-up on this phone is the fast engine: Blaze on the graphics chip — first words in about a second. Tap “Switch to the fast engine” above.": "Le plus gros gain de vitesse sur ce téléphone, c'est le moteur rapide : Blaze sur la puce graphique — premiers mots en une seconde environ. Touchez « Passer au moteur rapide » ci-dessus.",
