  "e.g. slide 4: shorter, add prices · delete slide 6 · add a slide about safety after slide 5": "p. ex. diapositive 4 : plus court, ajouter les prix · supprimer la diapositive 6 · ajouter une diapositive sur la sécurité après la 5",
