  "I couldn't read these files on the phone.": "Je n'ai pas pu lire ces fichiers sur le téléphone.",
  "What's in these files? Summarise what matters in each.": "Que contiennent ces fichiers ? Résume l'essentiel de chacun.",
  "Save to Shelf": "Enregistrer dans Étagère",
  "Import notes": "Importer des notes",
