  "not read: {f}": "non lu : {f}",
  "From the phone's Notebook app: open a note (or select several) → Share → Attune → “Save to Shelf”. Or pick exported files here: text, Word, PDF, web pages, Google Keep, Evernote, a .zip, or photos of notes.": "Depuis l'application Notebook du téléphone : ouvrez une note (ou sélectionnez-en plusieurs) → Partager → Attune → « Enregistrer dans Étagère ». Ou choisissez ici des fichiers exportés : texte, Word, PDF, pages web, Google Keep, Evernote, un .zip, ou des photos de notes.",
  "Versions & prices": "Versions et prix",
  "Pros & cons": "Avantages et inconvénients",
  "Compare with rivals": "Comparer avec les concurrents",
  "Latest news": "Dernières actualités",
  "Those results were off-topic — searching another way…": "Ces résultats étaient hors sujet — nouvelle recherche autrement…",
  "Nothing found for that — try the area's name too (e.g. “… New Cairo”), or move the map there and search again.": "Rien trouvé — essayez aussi le nom du quartier (p. ex. « … Nouvelle Le Caire »), ou déplacez la carte là-bas et relancez la recherche.",
  "from the map's centre": "depuis le centre de la carte",
  "saved place": "lieu enregistré",
  "Save this place": "Enregistrer ce lieu",
  "This phone can't share its location with the app.": "Ce téléphone ne peut pas partager sa position avec l'application.",
  "Location is off for Attune — allow it in the phone's settings to see where you are.": "La localisation est désactivée pour Attune — autorisez-la dans les réglages du téléphone pour voir où vous êtes.",
  "Couldn't get your location — check that location is on.": "Impossible d'obtenir votre position — vérifiez que la localisation est activée.",
  "“{n}” isn't kept on this phone any more — pick the file again.": "« {n} » n'est plus conservé sur ce téléphone — choisissez à nouveau le fichier.",
  "tap to continue": "touchez pour continuer",
  "The text and your questions are kept on this phone only. Forget removes them.": "Le texte et vos questions sont conservés uniquement sur ce téléphone. Oublier les supprime.",
  "Web · Auto": "Web · Auto",
  "Web: Auto — it searches only when a question needs fresh facts": "Web : Auto — il ne cherche que lorsqu'une question demande des faits récents",
  "Pick the best model for each question": "Choisir le meilleur modèle pour chaque question",
  "Reading your {f} conversation…": "Lecture de votre conversation {f}…",
  "Reading the conversation…": "Lecture de la conversation…",
  "Shared links are opened in the Android app — or paste the conversation's text here.": "Les liens partagés s'ouvrent dans l'application Android — ou collez ici le texte de la conversation.",
  "I read your conversation with {f}{t} (about {n} words). Ask me anything about it — check it, summarise it, or carry on from where it stopped.": "J'ai lu votre conversation avec {f}{t} (environ {n} mots). Posez-moi n'importe quelle question : vérifiez-la, résumez-la ou reprenez là où elle s'est arrêtée.",
  "Attune · the AI runs on your device · no account, no sign-in · web lookup only when a question needs it (Auto) — switch it off with the Web button": "Attune · l'IA tourne sur votre appareil · sans compte, sans connexion · recherche web seulement quand une question en a besoin (Auto) — désactivez-la avec le bouton Web",
  "Web: Off — nothing is looked up": "Web : Désactivé — rien n'est recherché",
  "While Web is off in Chat, questions about prices, specs, news, scores or this year are still looked up (only the search words leave the phone). Off: nothing is looked up unless you turn Web on.": "Quand Web est désactivé dans Discussion, les questions sur les prix, caractéristiques, actualités, scores ou l'année en cours sont quand même recherchées (seuls les mots de recherche quittent le téléphone). Désactivé : rien n'est recherché tant que vous n'activez pas Web.",
  "The model wrote nonsense — restarting it in safe mode and asking again…": "Le modèle a écrit n'importe quoi — redémarrage en mode sécurisé et nouvelle question…",
  "This model writes nonsense on this phone, even in safe mode. Pick another model in Engine (Core works well) and tell us which one failed.": "Ce modèle écrit n'importe quoi sur ce téléphone, même en mode sécurisé. Choisissez un autre modèle dans Moteur (Core fonctionne bien) et dites-nous lequel a échoué.",
  "Safe mode is on for this model: it once wrote nonsense on this phone, so it runs without speed tricks and with full-precision memory (a little slower, same answers).": "Le mode sécurisé est activé pour ce modèle : il a écrit n'importe quoi sur ce téléphone, il tourne donc sans accélérations et avec une mémoire en pleine précision (un peu plus lent, mêmes réponses).",
  "Turn safe mode off": "Désactiver le mode sécurisé",
  "Or any topic you like": "Ou n'importe quel sujet",
  "I can answer about your next period, being late, ovulation, the fertile window, cycle and period length, your history and symptoms.": "Je peux répondre sur vos prochaines règles, un retard, l'ovulation, la période fertile, la durée du cycle et des règles, votre historique et vos symptômes.",
  "Queued": "En file",
  "Best of 2": "Meilleur de 2",
